  if (m < 1000) return `±${Math.round(m)} m`
  const km = m / 1000
  return `±${km < 10 ? km.toFixed(1) : Math.round(km).toLocaleString('en-GB')} km`
}

export function distanceText(km: number): string {
  if (km < 1) return `${Math.round(km * 1000)} m`
  return `${km < 10 ? km.toFixed(1) : Math.round(km).toLocaleString('en-GB')} km`
}

/**
